//! The Code Mode cases upstream added in 2.2.6–2.2.7 (`packages/codemode/test`, v2.2.7): programs `import` and
//! `require` built-in globals by Node module name (#61151), and a top-level export is a parse error.
//!
//! `tests/fixtures/modules-2.2.7.json` holds programs run through upstream 2.2.7's Code Mode (legacy engine) with
//! their results, generated by a small bun script over the upstream checkout: plain runtimes, or one with a `files`
//! extension whose globals are `readFile(path)` (returns `text of <path>`) and async `stat(path)` (returns
//! `{path, size: 3}`). Every recorded result must be identical.

use std::sync::Arc;

use oc_codemode::codemode::{CodeMode, ExecutionLimits};
use oc_codemode::host::{
    Extension, HostCall, HostFunction, HostValue, NoTools, SimpleExtension, host_fn, host_fn_async,
};
use serde_json::{Value as Json, json};

fn plain() -> CodeMode {
    CodeMode::new(Vec::new(), Arc::new(NoTools), Vec::new(), ExecutionLimits::default()).unwrap()
}

fn with_files() -> CodeMode {
    let string_of = |args: &[HostValue]| match args.first() {
        Some(HostValue::String(s)) => s.clone(),
        _ => "undefined".to_string(),
    };
    let HostValue::Function(read_file) = host_fn("readFile", 1, move |args| {
        HostCall::Ready(Ok(HostValue::String(format!("text of {}", string_of(&args)))))
    }) else {
        unreachable!()
    };
    let HostValue::Function(stat) = host_fn_async("stat", 1, move |args| {
        let path = string_of(&args);
        HostCall::Pending(Box::pin(async move {
            Ok(HostValue::Object(vec![
                ("path".into(), HostValue::String(path)),
                ("size".into(), HostValue::Number(3.0)),
            ]))
        }))
    }) else {
        unreachable!()
    };
    let extension: Arc<dyn Extension> = Arc::new(SimpleExtension {
        name: "files".into(),
        globals: vec![
            ("readFile".into(), read_file as Arc<dyn HostFunction>),
            ("stat".into(), stat as Arc<dyn HostFunction>),
        ],
    });
    CodeMode::new(Vec::new(), Arc::new(NoTools), vec![extension], ExecutionLimits::default()).unwrap()
}

#[test]
fn imports_and_require_match_upstream() {
    let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/modules-2.2.7.json");
    let cases: Vec<Json> = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let (plain, files) = (plain(), with_files());
    let mut failures = Vec::new();
    for case in &cases {
        let code = case["code"].as_str().unwrap();
        let runtime = if case["extension"] == json!(true) { &files } else { &plain };
        let actual = runtime.execute_blocking(code).to_json();
        if actual != case["result"] {
            failures.push(format!("{code}\n  expected {}\n  actual   {actual}", case["result"]));
        }
    }
    assert!(cases.len() >= 80);
    assert!(failures.is_empty(), "{} of {} differ:\n{}", failures.len(), cases.len(), failures.join("\n"));
}

/// errors.test.ts "explains that exports aren't available".
#[test]
fn explains_that_exports_are_not_available() {
    let result = plain().execute_blocking("const x = 1\nexport { x }").to_json();
    assert_eq!(
        result["error"],
        json!({
            "kind": "ParseError",
            "message": "SyntaxError: Exports aren't available. Return the result instead. (line 2, col 1)",
            "location": { "line": 2, "column": 1 },
        })
    );
}

/// extensions.test.ts "a module that isn't provided, or a missing export, fails at the import" (the parts that use
/// built-in globals; upstream's object-valued `fs` extension global is not supported here).
#[test]
fn a_missing_module_or_export_fails_at_the_import() {
    let runtime = plain();
    let message =
        |code: &str| runtime.execute_blocking(code).to_json()["error"]["message"].as_str().unwrap().to_string();
    assert!(message(r#"import yaml from "yaml""#).starts_with(
        r#"Error: Cannot import "yaml": it isn't available in Code Mode, which can't load packages or files."#
    ));
    let caught =
        runtime.execute_blocking(r#"try { await import("child_process") } catch (e) { return e.message }"#).to_json();
    assert!(caught["value"].as_str().unwrap().starts_with(r#"Cannot import "child_process""#));
    assert!(
        message(r#"import { writeFile } from "url""#)
            .starts_with(r#"SyntaxError: "url" has no export named "writeFile"."#)
    );
    assert!(message(r#"require("fs")"#).starts_with(r#"Error: Cannot import "fs""#));
}

/// `scanTools` parses like `execute`: imports parse, a top-level export is the same `ParseError`, and a `tools`
/// reference in an import binding is not a static call.
#[test]
fn scan_tools_parses_modules() {
    use oc_codemode::scan::scan_tools;
    // Results of upstream 2.2.7's `scanTools` for the same programs.
    let alias = "Schedule checks must call tools directly as tools.<name>(...), not alias or pass the tools object.";
    let cases: [(&str, Result<Vec<&str>, String>); 6] = [
        ("import { URL } from \"url\"\nawait tools.a.b({})", Ok(vec!["a.b"])),
        (
            "export const x = tools.a.b()",
            Err("SyntaxError: Exports aren't available. Return the result instead. (line 1, col 1)".into()),
        ),
        ("import tools from \"tools\"", Err(format!("{alias} (line 1, col 8)"))),
        ("{ export const x = tools.a.b() }", Ok(vec!["a.b"])),
        ("const m = await import(tools.a.b())", Ok(vec!["a.b"])),
        ("import * as tools from \"url\"\ntools.x()", Err(format!("{alias} (line 1, col 13)"))),
    ];
    for (code, expected) in cases {
        let actual = scan_tools(code).map_err(|d| d.message);
        let expected = expected.map(|v| v.into_iter().map(String::from).collect::<Vec<_>>());
        assert_eq!(actual, expected, "{code}");
    }
}
